function personalPage(){const saved=wishlist().map(s=>products.find(p=>p.slug===s)).filter(Boolean),recent=readStore('jkc-recent',[]).map(s=>products.find(p=>p.slug===s)).filter(Boolean);shell(`<main class="wrap content"><p class="eyebrow">Saved on this device</p><h1>Your favourites</h1><div class="product-grid">${saved.map(productCard).join('')||'<p>No saved products yet. Use the Save button on a product page.</p>'}</div><h2>Recently viewed</h2><div class="product-grid">${recent.map(productCard).join('')||'<p>Your recently viewed products will appear here.</p>'}</div></main>`)}
