function expoPage(){shell(`<main class="wrap content expo"><p class="eyebrow">Fast counter mode</p><h1>Exhibition sales</h1><input id="expo-search" class="field" placeholder="Search name or SKU"><div id="expo-list"></div><div class="expo-total"><b>Bag: <span data-cart-count>0</span> items</b><a class="btn" href="cart.html">Checkout →</a></div></main>`);const draw=()=>{const q=$('#expo-search').value.toLowerCase(),a=products.filter(p=>(p.name+p.sku).toLowerCase().includes(q));$('#expo-list').innerHTML=a.map(p=>`<article class="expo-row"><img src="${p.images?.[0]||''}" alt=""><div><b>${p.name}</b><small>${p.sku} · ${stockLabel(p)}</small><strong>${money(p.offerPrice||p.price)}</strong></div><a class="btn secondary" href="${productUrl(p)}">Select</a></article>`).join('')};$('#expo-search').oninput=draw;draw()}
