function initUpgradeFeatures(){mobileBar();decorateReviewCards();if(!document.querySelector('link[rel="manifest"]'))document.head.insertAdjacentHTML('beforeend','<link rel="manifest" href="manifest.webmanifest"><meta name="theme-color" content="#ff5424">');if(settings.googleSiteVerification&&!document.querySelector('meta[name="google-site-verification"]'))document.head.insertAdjacentHTML('beforeend',`<meta name="google-site-verification" content="${safeAttr(settings.googleSiteVerification)}">`);if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('sw.js').catch(()=>{});if(cart.length&&!sessionStorage.getItem('jkc-cart-reminded'))setTimeout(()=>{toast(`Your bag still has ${cart.reduce((n,i)=>n+i.qty,0)} item(s)`);sessionStorage.setItem('jkc-cart-reminded','1')},2500)}
