function analyticsConsentMarkup(){const id=(settings.analyticsMeasurementId||'').trim();if(!/^G-[A-Z0-9]+$/i.test(id)||analyticsChoice())return'';return`<aside class="analytics-consent" aria-label="Analytics privacy choice"><div><b>Help us improve JK Chennai</b><p>Allow anonymous website analytics? No names, orders or payment details are shared. <a href="policies.html#privacy">Privacy</a></p></div><div class="actions"><button class="btn" onclick="setAnalyticsConsent('accepted')">Allow</button><button class="btn secondary" onclick="setAnalyticsConsent('declined')">Necessary only</button></div></aside>`}
window.setAnalyticsConsent=function(choice){try{localStorage.setItem(analyticsConsentKey,choice);localStorage.removeItem('lov2jk-analytics-consent')}catch{}document.cookie=`jkchennai_analytics_consent=${encodeURIComponent(choice)}; Max-Age=31536000; Path=/; SameSite=Lax${location.protocol==='https:'?'; Secure':''}`;document.querySelector('.analytics-consent')?.remove();if(choice==='accepted')loadAnalytics((settings.analyticsMeasurementId||'').trim())};
