function initSiteFeatures(){const b=settings.business||{},base=settings.siteUrl||location.origin+'/',store={"@context":"https://schema.org","@type":"OnlineStore","@id":`${base}#store`,name:settings.storeName||'JK Chennai',url:base,email:settings.email,telephone:`+${settings.whatsapp}`,description:settings.tagline,address:{"@type":"PostalAddress",streetAddress:b.address,addressLocality:'Chennai',addressRegion:'Tamil Nadu',postalCode:'600122',addressCountry:'IN'}};appendJsonLd(store,'store-schema');const id=(settings.analyticsMeasurementId||'').trim();if(analyticsChoice()==='accepted')loadAnalytics(id)}
function addProductSeo(p){const base=settings.siteUrl||location.href,canonical=`${base.replace(/\/$/,'')}/products/${encodeURIComponent(p.slug)}.html`,reviews=p.reviews||[],schema={"@context":"https://schema.org","@type":"Product",name:p.name,image:(p.images||[]).map(absoluteAsset),description:p.description,sku:p.sku,color:(p.colors||[]).join(', '),size:(p.sizes||[]).join(', '),brand:{"@type":"Brand",name:'JK Chennai'},offers:{"@type":"Offer",url:canonical,priceCurrency:'INR',price:Number(p.offerPrice||p.price),availability:p.available?'https://schema.org/InStock':'https://schema.org/OutOfStock',itemCondition:'https://schema.org/NewCondition'}};if(reviews.length){schema.aggregateRating={"@type":"AggregateRating",ratingValue:(reviews.reduce((n,r)=>n+Number(r.rating||5),0)/reviews.length).toFixed(1),reviewCount:reviews.length};schema.review=reviews.map(r=>({"@type":"Review",author:{"@type":"Person",name:r.name},reviewRating:{"@type":"Rating",ratingValue:Number(r.rating||5),bestRating:5},reviewBody:r.text}))}appendJsonLd(schema,'product-schema');let link=document.querySelector('link[rel="canonical"]');if(!link){link=document.createElement('link');link.rel='canonical';document.head.appendChild(link)}link.href=canonical;document.querySelector('meta[name="description"]')?.setAttribute('content',p.description)}
const pages={about:`<p class="eyebrow">Our story</p><h1>Joy lives in the little things.</h1><p>JK Chennai is a Chennai-born collection of cheerful dresses and imagination-sparking toys for children. We believe everyday products can feel special—without feeling precious.</p><h2>What we care about</h2><p>Comfort, honest product details, friendly human support and a colourful point of view. Every order is confirmed by a real person before you pay.</p>`,faq:`<p class="eyebrow">Questions, answered</p><h1>Good to know.</h1><details open><summary>How do I place an order?</summary><p>Add items to your bag, then send the ready-made order message on WhatsApp. We confirm stock, shipping and payment.</p></details><details><summary>How can I pay?</summary><p>After stock confirmation, pay by UPI, GPay, WhatsApp Pay or a secure payment link shared by us. Never pay an unverified account.</p></details><details><summary>Are website stock levels live?</summary><p>They are updated manually and may change. Final availability is always confirmed on WhatsApp.</p></details><details><summary>How do I choose a size?</summary><p>Message us with the child's age and measurements. We will help you choose before ordering.</p></details>`,tracking:`<p class="eyebrow">Order help</p><h1>Where is my order?</h1><div class="panel"><h2>Manual order updates</h2><p>Keep the order ID sent to you on WhatsApp. Tap below and include it in your message; our team will reply with the current status and tracking link, if dispatched.</p><a class="btn" id="track">Check on WhatsApp</a></div><h2>Typical journey</h2><ol><li>Order confirmed and payment received</li><li>Packed with care in Chennai</li><li>Handed to delivery partner</li><li>Tracking link shared on WhatsApp</li></ol>`,policies:`<p class="eyebrow">The clear details</p><h1>Store policies.</h1><h2 id="shipping">Shipping policy</h2><p>Orders are usually dispatched after payment confirmation. Delivery estimates and charges depend on your PIN code and are confirmed before payment. Delays caused by carriers or exceptional events will be communicated.</p><h2 id="returns">Return & refund policy</h2><p>Please contact us within 48 hours of delivery for a damaged, incorrect or defective item, with clear photos and an unboxing video where possible. Size exchanges depend on unused condition, tags and stock. Shipping charges may apply. Personalised and clearance items are normally final sale unless defective.</p><h2 id="privacy">Privacy policy</h2><p>We use the information you share only to answer enquiries, process orders, arrange delivery and provide support. We do not sell customer information. WhatsApp and payment providers process data under their own policies. Contact us to request correction or deletion of your order information, subject to legal record-keeping requirements.</p><h2>Website analytics</h2><p>With your permission, Google Analytics helps us understand anonymous website usage such as page visits, scrolling and outbound link clicks. We do not send customer names, WhatsApp order messages or payment details to Analytics. Google processes Analytics data under its own privacy terms.</p><button class="btn secondary" onclick="resetAnalyticsConsent()">Review analytics choice</button>`};
function trackingHtml(){const statuses=settings.orderStatuses?.length?settings.orderStatuses:[{name:'Confirmed',message:'Order confirmed and payment received'},{name:'Packed',message:'Packed with care in Chennai'},{name:'Shipped',message:'Handed to the delivery partner'},{name:'Delivered',message:'Delivery completed'}];return`<p class="eyebrow">Order help</p><h1>Where is my order?</h1><div class="panel"><h2>Manual order updates</h2><p>Keep the order ID sent to you on WhatsApp. Tap below and include it in your message; our team will reply with the current status and tracking link, if dispatched.</p><a class="btn" id="track">Check on WhatsApp</a></div><h2>Typical journey</h2><ol class="status-journey">${statuses.map(s=>`<li><b>${s.name}</b><span>${s.message}</span></li>`).join('')}</ol>`}
function info(name){let html=name==='tracking'?trackingHtml():pages[name],b=settings.business||{};if(name==='policies')html=html.replace('<h2>Website analytics</h2>','<h2>Optional customer accounts</h2><p>If you choose to sign in with Google, we receive your verified email address, name and profile picture. Cloudflare stores your saved products, delivery addresses and website order history for this service. We do not receive your Google password. You may use guest WhatsApp checkout without an account, and you may delete your customer account from the Profile section.</p><h2>Website analytics</h2>');if(name==='about')html=`<p class="eyebrow">Our story</p><h1>Joy lives in the little things.</h1><p>JK Chennai is a Chennai-born collection of cheerful garments and imagination-sparking toys for children. We believe everyday products can feel special—without feeling precious.</p><h2>About JK CHENNAI</h2><p>Founded by ${b.proprietorName||'Vanaja Jagannathan'}, the business commenced on ${b.commencementDate||'22 April 2025'}. We focus on comfortable garments, joyful toys, honest product details and friendly human support.</p><div class="panel business-card"><div><b>Brand name</b><p>${b.trademarkName||'JK Chennai'}</p><b>Nature of business</b><p>${b.nature||'Garments & Toys'}</p></div><div><b>Company</b><p>${b.companyName||'JK CHENNAI'}</p><b>Proprietor</b><p>${b.proprietorName||'Vanaja Jagannathan'}</p></div></div>`;if(name==='contact')html=`<p class="eyebrow">We're here</p><h1>Come say hello.</h1><div class="panel"><h2>WhatsApp is quickest</h2><p>Questions about size, stock, delivery or an order? Message our Chennai team.</p><a class="btn" href="${wa('Hello JK Chennai! I need some help.')}" target="_blank">Chat with JK Chennai</a><h2>Business contact</h2><p><b>${b.companyName||'JK CHENNAI'}</b><br>${b.address||''}</p><p><b>Phone:</b> +91 93635 29266<br><b>Email:</b> <a href="mailto:${settings.email}">${settings.email}</a></p></div>`;shell(`<main class="wrap content">${html}</main>`);if(name==='tracking')$('#track').href=wa('Hello JK Chennai! Please share the status of my order. My order ID is: ')}
