function versionedAsset(path){if(!path||/^(?:data:|blob:)/i.test(path))return path||'';const join=path.includes('?')?'&':'?';return`${path}${join}v=${encodeURIComponent(contentVersion||'current')}`}
function versionMedia(p,s,categoryData={},inventory={},pricing={},visibility={},reviewData={}){categories=(categoryData.categories||[]).map(c=>({...c,image:versionedAsset(c.image)})).sort((a,b)=>(a.order||999)-(b.order||999));const legacyCategory={Dresses:'dresses',Toys:'toys'},stockBySlug=new Map((inventory.products||[]).map(x=>[x.slug,Math.max(0,Number(x.stock)||0)])),priceBySlug=new Map((pricing.products||[]).map(x=>[x.slug,x])),visibilityBySlug=new Map((visibility.products||[]).map(x=>[x.slug,x.visible!==false])),reviewsBySlug=new Map((reviewData.products||[]).map(x=>[x.slug,x.reviews||[]]));products=(p.products||[]).map(x=>{const managed=stockBySlug.has(x.slug),stock=managed?stockBySlug.get(x.slug):Math.max(0,Number(x.stock)||0),prices=priceBySlug.get(x.slug),price=prices?Math.max(0,Number(prices.price)||0):x.price,offerPrice=prices&&prices.offerPrice!==null&&prices.offerPrice!==''?Math.max(0,Number(prices.offerPrice)||0):undefined,visible=visibilityBySlug.has(x.slug)?visibilityBySlug.get(x.slug):x.visible!==false,reviews=reviewsBySlug.has(x.slug)?reviewsBySlug.get(x.slug):x.reviews||[];return{...x,category:legacyCategory[x.category]||x.category,price,offerPrice,stock,visible,reviews,available:managed?stock>0:x.available!==false,images:(x.images||[]).filter(Boolean).map(versionedAsset),videoPoster:versionedAsset(x.videoPoster)}}).filter(x=>x.visible);const heroImages=(s.heroImages?.length?s.heroImages:[s.heroImage]).filter(Boolean).map(versionedAsset);settings={...s,lowStockThreshold:Math.max(0,Number(s.lowStockThreshold)||0),heroImages,heroImage:versionedAsset(s.heroImage),dressesCategoryImage:versionedAsset(s.dressesCategoryImage),toysCategoryImage:versionedAsset(s.toysCategoryImage),promotion:{...(s.promotion||{}),image:versionedAsset(s.promotion?.image),videoPoster:versionedAsset(s.promotion?.videoPoster)}}}
function applyVariantStock(data={}){const bySku=new Map((data.variants||[]).map(v=>[v.sku,Math.max(0,Number(v.stock)||0)]));products.forEach(p=>p.variants=(p.variants||[]).map(v=>({...v,stock:bySku.has(v.sku)?bySku.get(v.sku):Math.max(0,Number(v.stock)||0)})))}
Promise.all([fetchContent('content/products.json'),fetchContent('content/settings.json'),fetchContent('content/category-index.json'),fetchContent('content/stock.json'),fetchContent('content/prices.json'),fetchContent('content/visibility.json'),fetchContent('content/reviews.json'),fetchContent('content/orders.json')]).then(([p,s,c,i,pr,v,r,o])=>{contentVersion=[p.version,s.version,c.version,i.version,pr.version,v.version,r.version,o.version].filter(Boolean).join('-');versionMedia(p.data,s.data,c.data,i.data,pr.data,v.data,r.data);products.forEach(p=>p.reviews=(p.reviews||[]).filter(r=>r.approved!==false).map(r=>({...r,photo:versionedAsset(r.photo)})));initSiteFeatures();if(page==='home')editableHome();else if(page==='shop')shop();else if(page==='product'){product();rememberViewed(currentProductSlug());upgradeProductDetails();const actions=document.querySelector('.detail .actions');if(actions)actions.insertAdjacentHTML('beforeend',`<button class="btn secondary" onclick="toggleWishlist('${currentProductSlug()}',this)">${wishlistHas(currentProductSlug())?'♥ Saved':'♡ Save'}</button>`)}else if(page==='cart')upgradedCartPage();else if(page==='saved')personalPage();else if(page==='account'){shell('<main class="wrap content account-page"><p class="eyebrow">Customer account</p><h1>My JK Chennai</h1><div id="cloud-account"><p>Loading your secure account…</p></div></main>');window.initCloudAccount?.({settings,products,productCard})}else if(page==='tracking')orderTrackingPage(o.data);else if(page==='catalog')printableCatalog();else if(page==='expo')expoPage();else if(page==='stock-tools')stockTools();else info(page);initUpgradeFeatures()}).catch(()=>document.querySelector('#app').innerHTML='<main class="empty"><h1>We could not load the shop.</h1><p>Please refresh or message JK Chennai on WhatsApp.</p></main>');
